 def test_dark_client_owner_screens_clear_consent_and_public_controls(self):
  oid,docs=self.prepare_documents();link=self.create_link(oid,[docs[0]],False).json()['url'];self.save()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page(viewport={'width':375,'height':812});page.goto(link);checkbox=page.get_by_role('checkbox');expect(checkbox).not_to_be_checked();self.assertGreaterEqual(checkbox.bounding_box()['width'],24);self.assertGreaterEqual(checkbox.bounding_box()['height'],24);self.assertEqual(page.locator('body').evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(8, 12, 20)');self.assertEqual(page.get_by_role('link',name='Политика',exact=True).evaluate('(e)=>getComputedStyle(e).color'),'rgb(139, 183, 255)');self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));page.screenshot(path='/tmp/neuro-brand-consent-mobile.png',full_page=True);page.set_viewport_size({'width':1280,'height':900});page.screenshot(path='/tmp/neuro-brand-consent-desktop.png',full_page=True);checkbox.check();page.get_by_role('button',name='Продолжить к документам',exact=True).click();page.get_by_role('link',name='Скачать PDF',exact=True).wait_for();self.assertEqual(page.locator('article.card').evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(20, 28, 43)');self.assertEqual(page.get_by_role('button',name='Скачать точный текст',exact=True).count(),0)
   context=browser.new_context(viewport={'width':375,'height':812});context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);owner=context.new_page();errors=[];owner.on('pageerror',lambda e:errors.append(str(e)))
   for route in ['/studio.php','/workspace.php','/contract-settings.php','/client-settings.php','/payment-settings.php','/publication-owner.php?kind=portfolio','/help.php','/order-workflow.php?order='+str(oid)+'&stage=proposal']:
    owner.goto(self.base+route);owner.wait_for_load_state('networkidle');self.assertEqual(owner.locator('body').evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(8, 12, 20)',route);
    if owner.evaluate('document.documentElement.scrollWidth>innerWidth'):
     owner.screenshot(path='/tmp/neuro-brand-overflow.png',full_page=True);print('OVERFLOW',route,owner.evaluate("Array.from(document.querySelectorAll('body *')).filter(e=>e.getBoundingClientRect().right>innerWidth+1).map(e=>({tag:e.tagName,cls:e.className,right:e.getBoundingClientRect().right,text:e.textContent.slice(0,60)})).slice(-12)"),flush=True)
    self.assertFalse(owner.evaluate('document.documentElement.scrollWidth>innerWidth'),route)
    if 'publication-owner' in route:
     owner.get_by_role('button',name='Редактировать кейс и галерею',exact=True).click();owner.get_by_label('Краткое описание',exact=True).wait_for();self.assertEqual(owner.get_by_label('Название',exact=True).evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(13, 20, 34)');owner.screenshot(path='/tmp/neuro-brand-portfolio-mobile.png',full_page=True)
   self.assertEqual(errors,[]);owner.goto(self.base+'/customer.php?view=invite');self.assertEqual(owner.locator('body').evaluate('(e)=>getComputedStyle(e).backgroundColor'),'rgb(8, 12, 20)');browser.close()
 def test_outgoing_email_has_brand_html_safe_link_and_unchanged_plain_alternative(self):
  oid,docs=self.prepare_documents();self.smtp.messages.clear();response=self.create_link(oid,[docs[0]],True);self.assertEqual(response.status_code,200,response.text);self.assertTrue(response.json()['smtp_accepted']);self.assertEqual(len(self.smtp.messages),1);raw=self.smtp.messages[0][1];message=BytesParser(policy=policy.default).parsebytes(raw);self.assertTrue(message.is_multipart());self.assertEqual({p.get_content_type() for p in message.walk() if not p.is_multipart()},{'text/plain','text/html'});plain=message.get_body(preferencelist=('plain',)).get_content();html=message.get_body(preferencelist=('html',)).get_content();self.assertIn('Владелец НейроДело подготовил документы',plain);self.assertIn(self.base+'/prospect.php#token=',plain);self.assertIn('НейроДело',message['From']);self.assertIn('#080c14',html);self.assertIn('#ff3da6',html);self.assertIn('Открыть документы',html);self.assertNotIn('<script',html);self.assertNotIn('<img',html)
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page(viewport={'width':375,'height':812});requests=[];page.on('request',lambda r:requests.append(r.url));page.set_content(html);self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(requests,[]);page.screenshot(path='/tmp/neuro-brand-email-mobile.png',full_page=True);page.set_viewport_size({'width':1000,'height':900});page.screenshot(path='/tmp/neuro-brand-email-desktop.png',full_page=True);browser.close()
